import random, math
def syl(n):
    H=[[1]]
    while len(H)<n:
        m=len(H); NH=[[0]*(2*m) for _ in range(2*m)]
        for i in range(m):
            for j in range(m):
                v=H[i][j]; NH[i][j]=v; NH[i][j+m]=v; NH[i+m][j]=v; NH[i+m][j+m]=-v
        H=NH
    return H
n=64; s=1/math.sqrt(n)
H=[[v*s for v in row] for row in syl(n)]
def mm(A,B):
    k=len(B); p=len(B[0])
    return [[sum(A[i][t]*B[t][j] for t in range(k)) for j in range(p)] for i in range(len(A))]
G=mm(H,[row[:] for row in H])
print("orth dev |HH^T-I| = %.2e"%max(abs(G[i][j]-(1.0 if i==j else 0.0)) for i in range(n) for j in range(n)))
random.seed(0); rows,cols=128,64
W=[[random.gauss(0,0.02) for _ in range(cols)] for _ in range(rows)]
oc=[7,33,51]
for r in range(rows):
    for c in oc: W[r][c]*=25.0
Wh=mm(W,H)
fro=lambda A: math.sqrt(sum(v*v for rr in A for v in rr))
print("Frobenius rel diff = %.2e"%abs(fro(W)-fro(Wh))/1 if False else ("Frobenius rel diff = %.2e"%(abs(fro(W)-fro(Wh))/fro(W))))
def grpmax(A,g):
    v=[max(abs(x) for x in row[st:st+g]) for row in A for st in range(0,len(row),g)]
    return sum(v)/len(v)
def diag(A,b,g,skip):
    tot=0.0; en=0.0; mae=0.0; mx=0.0; c=0
    for row in A:
        for st in range(0,len(row),g):
            grp=row[st:st+g]; am=max(abs(v) for v in grp) or 1e-12
            L=(1<<(b-1))-1; step=am/L
            for i,v in enumerate(grp):
                q=max(-L-1,min(L,round(v/step)))*step; e=abs(v-q)
                if st+i not in skip:
                    tot+=e*e; en+=v*v; mae+=e; mx=max(mx,e); c+=1
    return math.sqrt(tot/max(en,1e-30)), mae/c, mx
print("mean per-group absmax: raw=%.4f rot=%.4f (%.2fx)"%(grpmax(W,64),grpmax(Wh,64),grpmax(W,64)/grpmax(Wh,64)))
for b in (4,3,2):
    for g in (32,64):
        a=diag(W,b,g,set(oc)); bh=diag(Wh,b,g,set(oc))
        print("b=%d g=%-3d non-outlier relRMSE raw=%.4f rot=%.4f ratio=%.2f | MAE raw=%.5f rot=%.5f"%(b,g,a[0],bh[0],bh[0]/a[0],a[1],bh[1]))
